// WebMCP (Web Model Context Protocol) — exposes this site as agent-callable tools.
// Progressive enhancement: the whole module stays inert unless the browser
// implements the draft ModelContext API (navigator.modelContext in Chromium; the
// spec text also references document.modelContext, so both are probed). Only then
// is the manifest fetched — /webmcp.json is generated by Jekyll from the same YAML
// sources as the human-facing pages, and read-only tools answer from it.
(function () {
  'use strict';
  const container = window.navigator.modelContext || window.document.modelContext;
  if (!container || typeof container.registerTool !== 'function') return;
  if (typeof window.fetch !== 'function') return;
  const script = document.currentScript || document.querySelector('[data-webmcp-manifest-url]');
  const manifestUrl = script && script.dataset ? script.dataset.webmcpManifestUrl : '';
  if (!manifestUrl) return;

  const register = (tool) => {
    try {
      const pending = container.registerTool(tool);
      if (pending && typeof pending.catch === 'function') pending.catch(() => {});
    } catch (_error) {
      // A browser that half-implements the draft must never break the page.
    }
  };

  const emptySchema = { type: 'object', properties: {} };

  const registerTools = (manifest) => {
    register({
      name: 'get_site_overview',
      description: 'Get an overview of Henrique Lavezzo\'s personal website: what it is, the main sections with their URLs and purposes, and where the RSS feed and sitemap live. Call this first to orient yourself on the site.',
      inputSchema: emptySchema,
      execute: () => ({
        title: manifest.site.title,
        description: manifest.site.description,
        url: manifest.site.url,
        feed_url: manifest.site.feed_url,
        sitemap_url: manifest.site.sitemap_url,
        sections: manifest.navigation.primary.concat(manifest.navigation.secondary)
      })
    });

    register({
      name: 'get_profile',
      description: 'Get professional identity facts about Henrique Lavezzo: tagline, current role and company, location, skills, and social links.',
      inputSchema: emptySchema,
      execute: () => ({
        name: manifest.site.author,
        email: manifest.site.email,
        tagline: manifest.profile.tagline,
        role: manifest.profile.role,
        current_title: manifest.profile.current_title,
        current_company: manifest.profile.current_company,
        location: manifest.profile.location,
        skills: manifest.profile.skills,
        social_links: manifest.profile.social_links
      })
    });

    register({
      name: 'get_current_focus',
      description: 'Get what Henrique is currently working on and focused on (the site\'s "now" page data): active quests, ongoing projects, and personal side paths, with the date this snapshot was last revised.',
      inputSchema: emptySchema,
      execute: () => ({
        updated_at: manifest.now.updated_at,
        focus: manifest.now.focus,
        side_paths: manifest.now.side_paths
      })
    });

    register({
      name: 'list_projects',
      description: 'List Henrique\'s software projects and artifacts (the site\'s Laboratory). Optionally filter by category: flagship, research, tools, personal, or archive. Returns title, role, status, summary, repository URL, and tags for each project.',
      inputSchema: {
        type: 'object',
        properties: {
          category: {
            type: 'string',
            description: 'Optional category filter.',
            enum: ['flagship', 'research', 'tools', 'personal', 'archive']
          }
        }
      },
      execute: (params) => {
        const projects = params && params.category
          ? manifest.projects.filter((project) => project.category === params.category)
          : manifest.projects;
        return { count: projects.length, projects };
      }
    });

    register({
      name: 'search_notes',
      description: 'Search Henrique\'s Field Notes (blog posts / essays) by keyword. Matches against titles, summaries, categories, and tags. Returns ranked results with URLs that can be opened or cited. Use an empty query to list all notes, most recent first.',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Keywords to search for (e.g. "architecture", "LLM", "Clojure"). Leave empty to list every note.'
          },
          limit: {
            type: 'number',
            description: 'Maximum number of results to return (default 10).'
          }
        }
      },
      execute: (params) => {
        const query = (params && params.query ? params.query : '').trim().toLowerCase();
        const limit = Math.min(Math.max((params && params.limit) || 10, 1), 50);
        const terms = query.split(/\s+/).filter(Boolean);
        const scored = manifest.posts
          .map((post) => {
            if (terms.length === 0) return { post, score: 1 };
            const title = post.title.toLowerCase();
            const resume = (post.resume || '').toLowerCase();
            const categories = (post.categories || []).join(' ').toLowerCase();
            const tags = (post.tags || []).join(' ').toLowerCase();
            let score = 0;
            terms.forEach((term) => {
              if (title.includes(term)) score += 3;
              if (tags.includes(term)) score += 2;
              if (categories.includes(term)) score += 2;
              if (resume.includes(term)) score += 1;
            });
            return { post, score };
          })
          .filter((entry) => entry.score > 0)
          .sort((a, b) => b.score - a.score)
          .slice(0, limit)
          .map((entry) => entry.post);
        return { query, count: scored.length, notes: scored };
      }
    });
  };

  window.fetch(manifestUrl, { credentials: 'same-origin' })
    .then((response) => {
      if (!response.ok) throw new Error('WebMCP manifest unavailable');
      return response.json();
    })
    .then(registerTools)
    .catch(() => {});
}());
